SELECT 'STOCK001.SH', 'a_share', 'SSE', '2', 'use', '股票自选演示', NOW(), NOW()
WHERE NOT EXISTS
(
    SELECT 1 FROM `my_security_pool`
    WHERE `security_code` = 'STOCK001.SH' AND `user_id` = '2' AND `status` = 'use'
);

